CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_address text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, push_token text NOT NULL, platform text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS perpl_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, environment text NOT NULL CHECK(environment IN ('testnet','mainnet')), scope text NOT NULL CHECK(scope IN ('read','trade')), credential_reference text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS books (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, market text NOT NULL, side text NOT NULL CHECK(side IN ('LONG','SHORT')), stance text NOT NULL CHECK(stance IN ('DEFEND','HARVEST','KILL')), liquidation_floor numeric NOT NULL CHECK(liquidation_floor >= 0), defense_cap numeric NOT NULL CHECK(defense_cap > 0), time_limit_ms bigint NOT NULL CHECK(time_limit_ms > 0), automation_enabled boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS positions (book_id uuid PRIMARY KEY REFERENCES books(id) ON DELETE CASCADE, size numeric NOT NULL, entry_price numeric NOT NULL, mark_price numeric NOT NULL, liquidation_price numeric NOT NULL, leverage numeric NOT NULL, unrealized_pnl numeric NOT NULL, margin numeric NOT NULL, status text NOT NULL);
CREATE TABLE IF NOT EXISTS reserves (book_id uuid PRIMARY KEY REFERENCES books(id) ON DELETE CASCADE, available numeric NOT NULL DEFAULT 0, reserved numeric NOT NULL DEFAULT 0, deployed numeric NOT NULL DEFAULT 0, cap numeric NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(available >= 0 AND reserved >= 0 AND deployed >= 0), CHECK(deployed + reserved <= cap));
CREATE TABLE IF NOT EXISTS risk_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, block bigint NOT NULL, timestamp timestamptz NOT NULL, mark numeric NOT NULL, oracle numeric NOT NULL, liquidation numeric NOT NULL, funding numeric NOT NULL, spread numeric NOT NULL, depth numeric NOT NULL, volatility numeric NOT NULL, reserve numeric NOT NULL, freshness numeric NOT NULL, source text NOT NULL, freshness_detail jsonb);
CREATE TABLE IF NOT EXISTS decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, state text NOT NULL, action text NOT NULL, reason_codes jsonb NOT NULL, human_readable_reasons jsonb NOT NULL, risk_features jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, decision_id uuid NOT NULL REFERENCES decisions(id), kind text NOT NULL, amount numeric NOT NULL DEFAULT 0, status text NOT NULL, idempotency_key text UNIQUE NOT NULL, venue_reference text, submitted_at timestamptz, confirmed_at timestamptz, failed_at timestamptz, error text);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_action_per_book ON actions(book_id) WHERE status IN ('QUEUED','VALIDATING','SUBMITTING','SUBMITTED','VERIFYING','UNKNOWN');
CREATE TABLE IF NOT EXISTS autopsy_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, type text NOT NULL, payload jsonb NOT NULL, block bigint, timestamp timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, title text NOT NULL, body text NOT NULL, dedupe_key text UNIQUE NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS books_user_idx ON books(user_id); CREATE INDEX IF NOT EXISTS risk_snapshots_book_time_idx ON risk_snapshots(book_id, timestamp DESC); CREATE INDEX IF NOT EXISTS autopsy_book_time_idx ON autopsy_events(book_id, timestamp DESC); CREATE INDEX IF NOT EXISTS notifications_user_time_idx ON notifications(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, wallet_address text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS auth_challenges(address text NOT NULL, nonce text NOT NULL, expires_at bigint NOT NULL, message text NOT NULL, consumed_at timestamptz, PRIMARY KEY(address,nonce));
CREATE TABLE IF NOT EXISTS reserve_ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, type text NOT NULL CHECK(type IN ('RESERVE_CREATED','RESERVE_RESERVED','RESERVE_DEPLOYED','RESERVE_RELEASED','RESERVE_RECONCILED')), amount numeric NOT NULL CHECK(amount >= 0), action_id uuid REFERENCES actions(id), decision_id uuid REFERENCES decisions(id), external_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reserve_ledger_book_time_idx ON reserve_ledger_entries(book_id, created_at DESC);

